"""Window management: list/focus/tile, DPI-aware, built on pygetwindow + Win32.

Additive v2 replacement for v1's tile_windows.py / human_demo.py window-finding
logic, generalized to arbitrary title substrings instead of hardcoded
Chrome/Spline/Antigravity strings.
"""

from __future__ import annotations

import ctypes
from ctypes import windll

from models import WindowInfo

try:
    import pygetwindow as gw
except ImportError:  # pragma: no cover - only missing outside the target venv
    gw = None


def get_dpi_scale() -> float:
    """Return the primary monitor's DPI scale factor (1.0 == 96 DPI == 100%)."""
    try:
        windll.shcore.SetProcessDpiAwareness(2)
    except Exception:
        pass
    try:
        hdc = windll.user32.GetDC(0)
        dpi_x = windll.gdi32.GetDeviceCaps(hdc, 88)  # LOGPIXELSX
        windll.user32.ReleaseDC(0, hdc)
        return round(dpi_x / 96.0, 4)
    except Exception:
        return 1.0


def get_screen_size() -> tuple[int, int]:
    width = windll.user32.GetSystemMetrics(0)
    height = windll.user32.GetSystemMetrics(1)
    return width, height


def _to_window_info(w) -> WindowInfo:
    return WindowInfo(
        title=w.title,
        left=w.left,
        top=w.top,
        width=w.width,
        height=w.height,
        is_active=_safe(lambda: w.isActive, False),
        is_minimized=_safe(lambda: w.isMinimized, False),
    )


def _safe(fn, default):
    try:
        return fn()
    except Exception:
        return default


def list_windows(title_substring: str | None = None) -> list[WindowInfo]:
    if gw is None:
        return []
    windows = [w for w in gw.getAllWindows() if w.title.strip()]
    if title_substring:
        needle = title_substring.lower()
        windows = [w for w in windows if needle in w.title.lower()]
    return [_to_window_info(w) for w in windows]


def find_window(title_substring: str):
    if gw is None:
        return None
    needle = title_substring.lower()
    for w in gw.getAllWindows():
        if needle in w.title.lower():
            return w
    return None


def focus_window(title_substring: str) -> WindowInfo | None:
    win = find_window(title_substring)
    if win is None:
        return None
    try:
        if win.isMinimized:
            win.restore()
        win.activate()
    except Exception:
        pass
    return _to_window_info(win)


def tile_windows(
    left_title_substring: str, right_title_substring: str
) -> tuple[WindowInfo | None, WindowInfo | None]:
    """Tile two windows left/right across the primary display, matched by
    case-insensitive title substring. Returns (left_info, right_info); either may be
    None if no matching window was found."""
    screen_width, screen_height = get_screen_size()
    half_width = screen_width // 2

    left_info = None
    left_win = find_window(left_title_substring)
    if left_win is not None:
        try:
            left_win.restore()
            left_win.activate()
            left_win.resizeTo(half_width, screen_height)
            left_win.moveTo(0, 0)
        except Exception:
            pass
        left_info = _to_window_info(left_win)

    right_info = None
    right_win = find_window(right_title_substring)
    if right_win is not None:
        try:
            right_win.restore()
            right_win.activate()
            right_win.resizeTo(screen_width - half_width, screen_height)
            right_win.moveTo(half_width, 0)
        except Exception:
            pass
        right_info = _to_window_info(right_win)

    return left_info, right_info

"""Shared action engine: screen capture, grounding, mouse/keyboard, verify-after-action.

All MCP tools in server.py delegate here. Keeping the engine separate from the MCP
transport means it can also be driven from a plain CLI/tests without stdio plumbing,
matching how v1 split universal_controller.py from server.py — except here EVERY
action (not just click_text) is exposed and typed.
"""

from __future__ import annotations

import os
import time
import uuid
from pathlib import Path

import pyautogui

from models import (
    BoundingBox,
    ClickResult,
    DragResult,
    FindResult,
    KeyResult,
    OpenPathResult,
    ScreenCaptureResult,
    ScreenInspectResult,
    ScrollResult,
    TypeTextResult,
    WaitForTextResult,
)
from vision_engine import VisionEngine

pyautogui.FAILSAFE = True
pyautogui.MINIMUM_DURATION = 0.1
pyautogui.PAUSE = 0.3

RUNS_DIR = Path(__file__).parent / "runs"
RUNS_DIR.mkdir(exist_ok=True)

DEFAULT_MOVE_DURATION = 0.5
OCR_CONFIDENCE_MIN_MATCHES = 1


class ControllerCore:
    def __init__(self) -> None:
        self.vision = VisionEngine()

    # -- capture -----------------------------------------------------------------

    def _new_screenshot_path(self, prefix: str) -> str:
        name = f"{prefix}_{int(time.time() * 1000)}_{uuid.uuid4().hex[:6]}.png"
        return str(RUNS_DIR / name)

    def screen_capture(self, label: str = "capture") -> ScreenCaptureResult:
        start = time.monotonic()
        try:
            path = self._new_screenshot_path(label)
            img = pyautogui.screenshot()
            img.save(path)
            width, height = img.size
            screen_w, _ = pyautogui.size()
            scale = round(width / screen_w, 4) if screen_w else 1.0
            return ScreenCaptureResult(
                ok=True,
                tool="screen_capture",
                message=f"Captured {width}x{height} screenshot",
                image_path=path,
                screenshot_path=path,
                width=width,
                height=height,
                scale_factor=scale,
                duration_ms=int((time.monotonic() - start) * 1000),
            )
        except Exception as exc:
            return ScreenCaptureResult(
                ok=False, tool="screen_capture", error=str(exc),
                duration_ms=int((time.monotonic() - start) * 1000),
            )

    def screen_inspect(self, use_gemini_labels: bool = False) -> ScreenInspectResult:
        start = time.monotonic()
        cap = self.screen_capture(label="inspect")
        if not cap.ok or not cap.image_path:
            return ScreenInspectResult(ok=False, tool="screen_inspect", error=cap.error)
        try:
            matches, full_text = self.vision.ocr(cap.image_path)
            return ScreenInspectResult(
                ok=True,
                tool="screen_inspect",
                message=f"OCR found {len(matches)} text regions",
                image_path=cap.image_path,
                screenshot_path=cap.image_path,
                matches=matches,
                full_text=full_text,
                duration_ms=int((time.monotonic() - start) * 1000),
            )
        except Exception as exc:
            return ScreenInspectResult(
                ok=False, tool="screen_inspect", error=str(exc),
                image_path=cap.image_path, screenshot_path=cap.image_path,
                duration_ms=int((time.monotonic() - start) * 1000),
            )

    # -- grounding -----------------------------------------------------------------

    def find_text(self, target_text: str, use_gemini_fallback: bool = True) -> FindResult:
        start = time.monotonic()
        cap = self.screen_capture(label="find_text")
        if not cap.ok or not cap.image_path:
            return FindResult(ok=False, tool="find_text", error=cap.error)

        try:
            candidates = self.vision.find_text(cap.image_path, target_text)
        except Exception as exc:
            return FindResult(
                ok=False, tool="find_text", error=str(exc),
                screenshot_path=cap.image_path,
                duration_ms=int((time.monotonic() - start) * 1000),
            )

        if candidates:
            best = candidates[0]
            return FindResult(
                ok=True, tool="find_text",
                message=f"Found '{target_text}' via OCR ({len(candidates)} candidate(s))",
                found=True, x=best.x, y=best.y, box=best.box,
                candidates=candidates, source="vision_ocr",
                screenshot_path=cap.image_path,
                duration_ms=int((time.monotonic() - start) * 1000),
            )

        if use_gemini_fallback:
            hit = self.vision.find_element_gemini(cap.image_path, target_text)
            if hit is not None:
                return FindResult(
                    ok=True, tool="find_text",
                    message=f"Found '{target_text}' via Gemini fallback",
                    found=True, x=hit.x, y=hit.y, box=hit.box,
                    candidates=[hit], source="gemini",
                    screenshot_path=cap.image_path,
                    duration_ms=int((time.monotonic() - start) * 1000),
                )

        return FindResult(
            ok=True, tool="find_text", found=False,
            message=f"'{target_text}' not found on screen",
            screenshot_path=cap.image_path, source="none",
            duration_ms=int((time.monotonic() - start) * 1000),
        )

    def find_element(self, description: str) -> FindResult:
        """Non-text UI element grounding (icons, sliders, canvas handles) via Gemini,
        falling back to OCR in case the description is actually a text label."""
        start = time.monotonic()
        cap = self.screen_capture(label="find_element")
        if not cap.ok or not cap.image_path:
            return FindResult(ok=False, tool="find_element", error=cap.error)

        hit = self.vision.find_element_gemini(cap.image_path, description)
        if hit is not None:
            return FindResult(
                ok=True, tool="find_element", found=True,
                message=f"Found '{description}' via Gemini",
                x=hit.x, y=hit.y, box=hit.box, candidates=[hit], source="gemini",
                screenshot_path=cap.image_path,
                duration_ms=int((time.monotonic() - start) * 1000),
            )

        try:
            candidates = self.vision.find_text(cap.image_path, description)
        except Exception:
            candidates = []
        if candidates:
            best = candidates[0]
            return FindResult(
                ok=True, tool="find_element", found=True,
                message=f"Found '{description}' via OCR fallback",
                x=best.x, y=best.y, box=best.box, candidates=candidates, source="vision_ocr",
                screenshot_path=cap.image_path,
                duration_ms=int((time.monotonic() - start) * 1000),
            )

        return FindResult(
            ok=True, tool="find_element", found=False,
            message=f"'{description}' not found on screen",
            screenshot_path=cap.image_path, source="none",
            duration_ms=int((time.monotonic() - start) * 1000),
        )

    # -- mouse/keyboard actions -----------------------------------------------------

    def _resolve_target(self, x: int | None, y: int | None, target_text: str | None) -> tuple[int | None, int | None, FindResult | None]:
        if x is not None and y is not None:
            return x, y, None
        if target_text:
            found = self.find_text(target_text)
            if found.found and found.x is not None and found.y is not None:
                return found.x, found.y, found
            return None, None, found
        return None, None, None

    def click(
        self,
        x: int | None = None,
        y: int | None = None,
        target_text: str | None = None,
        button: str = "left",
        clicks: int = 1,
        verify: bool = True,
    ) -> ClickResult:
        start = time.monotonic()
        rx, ry, find_info = self._resolve_target(x, y, target_text)
        if rx is None or ry is None:
            return ClickResult(
                ok=False, tool="click",
                error=f"Could not resolve click target (text={target_text!r})",
                screenshot_path=find_info.screenshot_path if find_info else None,
                duration_ms=int((time.monotonic() - start) * 1000),
            )
        try:
            pyautogui.moveTo(rx, ry, duration=DEFAULT_MOVE_DURATION, tween=pyautogui.easeInOutQuad)
            pyautogui.click(button=button, clicks=clicks)
        except Exception as exc:
            return ClickResult(ok=False, tool="click", error=str(exc), x=rx, y=ry)

        verify_path = None
        if verify:
            post = self.screen_capture(label="click_verify")
            verify_path = post.image_path

        return ClickResult(
            ok=True, tool="click", message=f"Clicked at ({rx}, {ry})",
            x=rx, y=ry, button=button, clicks=clicks, verified=verify,
            screenshot_path=find_info.screenshot_path if find_info else None,
            verify_screenshot_path=verify_path,
            duration_ms=int((time.monotonic() - start) * 1000),
        )

    def double_click(
        self, x: int | None = None, y: int | None = None,
        target_text: str | None = None, verify: bool = True,
    ) -> ClickResult:
        return self.click(x=x, y=y, target_text=target_text, clicks=2, verify=verify)

    def drag(
        self, start_x: int, start_y: int, end_x: int, end_y: int,
        duration: float = 0.6, verify: bool = True,
    ) -> DragResult:
        start = time.monotonic()
        try:
            pyautogui.moveTo(start_x, start_y, duration=DEFAULT_MOVE_DURATION)
            pyautogui.dragTo(end_x, end_y, duration=duration, button="left")
        except Exception as exc:
            return DragResult(ok=False, tool="drag", error=str(exc))

        verify_path = None
        if verify:
            verify_path = self.screen_capture(label="drag_verify").image_path

        return DragResult(
            ok=True, tool="drag",
            message=f"Dragged ({start_x},{start_y}) -> ({end_x},{end_y})",
            start_x=start_x, start_y=start_y, end_x=end_x, end_y=end_y,
            verify_screenshot_path=verify_path,
            duration_ms=int((time.monotonic() - start) * 1000),
        )

    def scroll(self, amount: int, x: int | None = None, y: int | None = None) -> ScrollResult:
        start = time.monotonic()
        try:
            if x is not None and y is not None:
                pyautogui.moveTo(x, y, duration=DEFAULT_MOVE_DURATION)
            pyautogui.scroll(amount)
        except Exception as exc:
            return ScrollResult(ok=False, tool="scroll", error=str(exc))
        return ScrollResult(
            ok=True, tool="scroll", message=f"Scrolled {amount}", amount=amount, x=x, y=y,
            duration_ms=int((time.monotonic() - start) * 1000),
        )

    def type_text(self, text: str, interval: float = 0.02) -> TypeTextResult:
        start = time.monotonic()
        try:
            pyautogui.typewrite(text, interval=interval)
        except Exception as exc:
            return TypeTextResult(ok=False, tool="type_text", error=str(exc))
        return TypeTextResult(
            ok=True, tool="type_text", message=f"Typed {len(text)} characters",
            text_length=len(text), duration_ms=int((time.monotonic() - start) * 1000),
        )

    def press_key(self, key: str) -> KeyResult:
        start = time.monotonic()
        try:
            pyautogui.press(key)
        except Exception as exc:
            return KeyResult(ok=False, tool="press_key", error=str(exc), keys=[key])
        return KeyResult(
            ok=True, tool="press_key", message=f"Pressed '{key}'", keys=[key],
            duration_ms=int((time.monotonic() - start) * 1000),
        )

    def hotkey(self, keys: list[str]) -> KeyResult:
        start = time.monotonic()
        try:
            pyautogui.hotkey(*keys)
        except Exception as exc:
            return KeyResult(ok=False, tool="hotkey", error=str(exc), keys=keys)
        return KeyResult(
            ok=True, tool="hotkey", message=f"Pressed hotkey {'+'.join(keys)}", keys=keys,
            duration_ms=int((time.monotonic() - start) * 1000),
        )

    def open_path(self, path: str) -> OpenPathResult:
        start = time.monotonic()
        try:
            os.startfile(path)  # noqa: S606 - intentional, this IS the automation surface
        except Exception as exc:
            return OpenPathResult(ok=False, tool="open_path", error=str(exc), path=path)
        return OpenPathResult(
            ok=True, tool="open_path", message=f"Opened {path}", path=path,
            duration_ms=int((time.monotonic() - start) * 1000),
        )

    def wait_for_text(self, target_text: str, timeout_s: float = 10.0, poll_interval_s: float = 1.0) -> WaitForTextResult:
        start = time.monotonic()
        deadline = start + timeout_s
        while time.monotonic() < deadline:
            found = self.find_text(target_text, use_gemini_fallback=False)
            if found.found:
                return WaitForTextResult(
                    ok=True, tool="wait_for_text", found=True,
                    message=f"'{target_text}' appeared", elapsed_ms=int((time.monotonic() - start) * 1000),
                    match=found.candidates[0] if found.candidates else None,
                    screenshot_path=found.screenshot_path,
                )
            time.sleep(poll_interval_s)
        return WaitForTextResult(
            ok=True, tool="wait_for_text", found=False,
            message=f"'{target_text}' did not appear within {timeout_s}s",
            elapsed_ms=int((time.monotonic() - start) * 1000),
        )

"""hybrid_automation_v2 MCP server.

Additive v2 of the July 7 universal computer controller prototype. Unlike v1 --
where server.py only exposed find_text_coordinates and the real click logic lived
in a separate CLI script -- every action lives behind a typed MCP tool here, backed
by controller_core.ControllerCore, window_ops, and vision_engine.

Run directly with: uv run server.py
Registered as "hybrid_automation_v2" so it coexists with the untouched v1
"hybrid_automation" server.
"""

