@mcp.tool()
def run_action_plan(steps: list[dict]) -> RunActionPlanResult:
    """Run an ordered list of action steps in one call, verifying/screenshotting after
    each step, and stopping at the first failure. Each step is a dict matching
    models.ActionStep, e.g. {"action": "click", "target_text": "Export"}.
    Supported actions: screen_capture, click, double_click, drag, scroll, type_text,
    press_key, hotkey, focus_window, tile_windows, wait_for_text, open_path."""
    from models import ActionStep

    results: list[StepResult] = []
    stopped_early = False

    for idx, raw_step in enumerate(steps):
        step = ActionStep.model_validate(raw_step)
        try:
            result = _run_single_step(step)
        except Exception as exc:  # keep the plan resilient to a single bad step
            results.append(StepResult(step_index=idx, action=step.action, ok=False, error=str(exc)))
            stopped_early = True
            break

        results.append(
            StepResult(
                step_index=idx,
                action=step.action,
                ok=result.ok,
                message=result.message,
                error=result.error,
                screenshot_path=getattr(result, "verify_screenshot_path", None) or result.screenshot_path,
            )
        )
        if not result.ok:
            stopped_early = True
            break

    ok = len(results) > 0 and all(r.ok for r in results)
    return RunActionPlanResult(
        ok=ok,
        tool="run_action_plan",
        message=f"Ran {len(results)}/{len(steps)} step(s)",
        steps=results,
        stopped_early=stopped_early,
    )


def _run_single_step(step):
    if step.action == "screen_capture":
        return core.screen_capture()
    if step.action == "click":
        return core.click(x=step.x, y=step.y, target_text=step.target_text, verify=step.verify)
    if step.action == "double_click":
        return core.double_click(x=step.x, y=step.y, target_text=step.target_text, verify=step.verify)
    if step.action == "drag":
        return core.drag(step.x, step.y, step.end_x, step.end_y, verify=step.verify)
    if step.action == "scroll":
        return core.scroll(step.amount or 0, x=step.x, y=step.y)
    if step.action == "type_text":
        return core.type_text(step.text or "")
    if step.action == "press_key":
        return core.press_key(step.key or "")
    if step.action == "hotkey":
        return core.hotkey(step.keys or [])
    if step.action == "focus_window":
        info = window_ops.focus_window(step.window_title_substring or "")
        return FocusWindowResult(
            ok=info is not None, tool="focus_window",
            error=None if info else f"No window matching '{step.window_title_substring}'",
            window=info,
        )
    if step.action == "tile_windows":
        left_info, right_info = window_ops.tile_windows(
            step.window_title_substring or "", step.text or ""
        )
        ok = left_info is not None or right_info is not None
        return TileWindowsResult(ok=ok, tool="tile_windows", left_window=left_info, right_window=right_info)
    if step.action == "wait_for_text":
        return core.wait_for_text(step.target_text or "", timeout_s=step.timeout_s or 10.0)
    if step.action == "open_path":
        return core.open_path(step.path or "")
    raise ValueError(f"Unsupported action: {step.action}")


