    """Find the first visible top-level window owned by exactly `pid`, polling until
    it appears or `timeout_s` elapses. Precise alternative to title-substring matching
    for freshly-spawned scratch windows, so automation never accidentally grabs a
    pre-existing window that merely shares part of its title (e.g. any other Notepad)."""
    if win32gui is None or win32process is None or gw is None:
