def snapshot_titles() -> set[str]:
    """Capture the set of current top-level window titles, for diffing against after
    launching a new process. Robust alternative to PID matching for modern packaged
    apps (Notepad, Calculator, etc.) where the launcher PID differs from the actual
    window-owning host process PID."""
    if gw is None:
        return set()
    return {w.title for w in gw.getAllWindows() if w.title.strip()}


def find_new_window(before_titles: set[str], title_substring: str, timeout_s: float = 6.0, poll_interval_s: float = 0.25):
    """Poll until a window appears whose title contains `title_substring` (case
    insensitive) and was NOT present in `before_titles`. Returns the pygetwindow
    window object, or None on timeout."""
    if gw is None:
        return None

    import time as _time

    needle = title_substring.lower()
    deadline = _time.monotonic() + timeout_s
    while _time.monotonic() < deadline:
        for w in gw.getAllWindows():
            if not w.title.strip() or w.title in before_titles:
                continue
            if needle in w.title.lower():
                return w
        _time.sleep(poll_interval_s)
    return None


