// Iridescent dotted-wave boost pad shader.
// Look lineage: Joey's iridescent_dotted_wave Blender series + Refract legacy engines
// (electric blue -> magenta sweep over a dark dotted LED grid).
export const boostPadVertex = /* glsl */ `
varying vec2 vUv;
void main() {
  vUv = uv;
  gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
}
`;

export const boostPadFragment = /* glsl */ `
precision highp float;
varying vec2 vUv;
uniform float uTime;
uniform vec3 uColorA;
uniform vec3 uColorB;

void main() {
  vec2 uv = vUv;

  // Scrolling energy wave along the pad's travel direction.
  float wave = sin(uv.y * 14.0 - uTime * 6.0) * 0.5 + 0.5;
  float sweep = smoothstep(0.0, 1.0, fract(uv.y * 2.0 - uTime * 0.9));

  // LED dot grid.
  vec2 grid = fract(uv * vec2(22.0, 30.0)) - 0.5;
  float dot_ = smoothstep(0.32, 0.08, length(grid));

  // Iridescent hue drift between the two neon colors.
  vec3 color = mix(uColorA, uColorB, wave * 0.65 + sweep * 0.35);
  float energy = dot_ * (0.35 + wave * 0.85);

  // Edge glow rails on the pad sides.
  float edge = smoothstep(0.5, 0.46, abs(uv.x - 0.5));
  energy += (1.0 - edge) * 1.4;

  gl_FragColor = vec4(color * energy * 2.2, 1.0);
}
`;

import * as THREE from 'three';
import { Reflector } from 'three/addons/objects/Reflector.js';
import { boostPadVertex, boostPadFragment } from './shaders/boostPad.js';

export const PALETTE = {
  ink: 0x05060a,
  blue: 0x00a2ff,
  pink: 0xff1f6e,
  lime: 0x57ff6b,
  body: 0x0a0c12,
};

const TRACK_WIDTH = 26;

export function createArena(scene) {
  const group = new THREE.Group();
  scene.add(group);

  scene.background = new THREE.Color(PALETTE.ink);
  scene.fog = new THREE.FogExp2(PALETTE.ink, 0.0016);

  // Closed sweeping circuit with elevation.
  const curve = new THREE.CatmullRomCurve3(
    [
      new THREE.Vector3(0, 3, 0),
      new THREE.Vector3(150, 3, 0),
      new THREE.Vector3(260, 12, 60),
      new THREE.Vector3(300, 30, 180),
      new THREE.Vector3(220, 42, 300),
      new THREE.Vector3(80, 34, 360),
      new THREE.Vector3(-60, 22, 300),
      new THREE.Vector3(-120, 10, 160),
      new THREE.Vector3(-60, 4, 40),
    ],
    true,
    'catmullrom',
    0.35
  );

  const trackMesh = buildRibbon(curve, TRACK_WIDTH);
  group.add(trackMesh);

  const rails = buildRails(curve, TRACK_WIDTH);
  rails.forEach((rail) => group.add(rail));

  // Mirror-black floor plane far below the ribbon.
  const floor = new Reflector(new THREE.PlaneGeometry(2600, 2600), {
    clipBias: 0.003,
    textureWidth: 1024,
    textureHeight: 1024,
    color: 0x0a0d14,
  });
  floor.rotation.x = -Math.PI / 2;
  floor.position.y = -6;
  group.add(floor);

  const boostPads = [0.06, 0.3, 0.55, 0.8].map((t) => makeBoostPad(curve, t, group));
  const gates = buildGates(curve, group);
  addLighting(group);

  const spawn = getSpawn(curve, 0.005);

  return { group, curve, trackMesh, boostPads, gates, spawn };
}

function buildRibbon(curve, width) {
  const segments = 420;
  const positions = [];
  const uvs = [];
  const indices = [];
  const up = new THREE.Vector3(0, 1, 0);

  for (let i = 0; i <= segments; i++) {
    const t = i / segments;
    const point = curve.getPointAt(t);
    const tangent = curve.getTangentAt(t);
    const side = new THREE.Vector3().crossVectors(up, tangent).normalize();
    const half = side.multiplyScalar(width / 2);
    positions.push(point.x - half.x, point.y, point.z - half.z);
    positions.push(point.x + half.x, point.y, point.z + half.z);
    uvs.push(0, t * 40, 1, t * 40);
    if (i < segments) {
      const a = i * 2;
      indices.push(a, a + 1, a + 2, a + 1, a + 3, a + 2);
    }
  }

  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  geometry.setAttribute('uv', new THREE.Float32BufferAttribute(uvs, 2));
  geometry.setIndex(indices);
  geometry.computeVertexNormals();

  const material = new THREE.MeshPhysicalMaterial({
    color: 0x0b0e16,
    metalness: 0.85,
    roughness: 0.22,
    clearcoat: 1.0,
    clearcoatRoughness: 0.15,
    side: THREE.DoubleSide,
  });

  const mesh = new THREE.Mesh(geometry, material);
  mesh.userData.isTrack = true;
  return mesh;
}

function buildRails(curve, width) {
  const offsets = [-(width / 2 + 1.2), width / 2 + 1.2];
  const colors = [PALETTE.blue, PALETTE.pink];
  const up = new THREE.Vector3(0, 1, 0);

  return offsets.map((offset, index) => {
    const points = [];
    const samples = 360;
    for (let i = 0; i <= samples; i++) {
      const t = i / samples;
      const point = curve.getPointAt(t);
      const tangent = curve.getTangentAt(t);
      const side = new THREE.Vector3().crossVectors(up, tangent).normalize();
      points.push(point.clone().addScaledVector(side, offset).add(new THREE.Vector3(0, 0.9, 0)));
    }
    const railCurve = new THREE.CatmullRomCurve3(points, true);
    const geometry = new THREE.TubeGeometry(railCurve, 420, 0.32, 8, true);
    const material = new THREE.MeshStandardMaterial({
      color: 0x000000,
      emissive: new THREE.Color(colors[index]),
      emissiveIntensity: 3.2,
    });
    return new THREE.Mesh(geometry, material);
  });
}

function makeBoostPad(curve, t, group) {
  const point = curve.getPointAt(t);
  const tangent = curve.getTangentAt(t);
  const angle = Math.atan2(tangent.x, tangent.z);

  const material = new THREE.ShaderMaterial({
    vertexShader: boostPadVertex,
    fragmentShader: boostPadFragment,
    uniforms: {
      uTime: { value: 0 },
      uColorA: { value: new THREE.Color(PALETTE.blue) },
      uColorB: { value: new THREE.Color(PALETTE.pink) },
    },
  });

  const pad = new THREE.Mesh(new THREE.PlaneGeometry(10, 22), material);
  pad.rotation.x = -Math.PI / 2;
  pad.rotation.z = -angle;
  pad.position.copy(point).add(new THREE.Vector3(0, 0.25, 0));
  group.add(pad);

  return { mesh: pad, material, position: pad.position.clone(), radius: 12, cooldown: 0 };
}

function buildGates(curve, group) {
  const gateParams = [0.22, 0.46, 0.72, 0.985];
  const up = new THREE.Vector3(0, 1, 0);

  return gateParams.map((t, index) => {
    const isFinish = index === gateParams.length - 1;
    const point = curve.getPointAt(t);
    const tangent = curve.getTangentAt(t);
    const side = new THREE.Vector3().crossVectors(up, tangent).normalize();
    const color = isFinish ? PALETTE.lime : index % 2 === 0 ? PALETTE.blue : PALETTE.pink;

    const pillarGeometry = new THREE.CylinderGeometry(0.5, 0.5, 22, 12);
    const pillarMaterial = new THREE.MeshStandardMaterial({
      color: 0x000000,
      emissive: new THREE.Color(color),
      emissiveIntensity: 2.6,
    });

    for (const direction of [-1, 1]) {
      const pillar = new THREE.Mesh(pillarGeometry, pillarMaterial);
      pillar.position.copy(point).addScaledVector(side, direction * (TRACK_WIDTH / 2 + 2.4));
      pillar.position.y += 11;
      group.add(pillar);
    }

    const beam = new THREE.Mesh(
      new THREE.BoxGeometry(TRACK_WIDTH + 6, 0.6, 0.6),
      new THREE.MeshStandardMaterial({
        color: 0x000000,
        emissive: new THREE.Color(color),
        emissiveIntensity: 3.0,
      })
    );
    beam.position.copy(point);
    beam.position.y += 22;
    beam.rotation.y = Math.atan2(tangent.x, tangent.z) + Math.PI / 2;
    group.add(beam);

    return { position: point.clone(), radius: TRACK_WIDTH / 2 + 6, index, isFinish };
  });
}

function addLighting(group) {
  const ambient = new THREE.AmbientLight(0x1a2030, 0.7);
  group.add(ambient);

  const key = new THREE.DirectionalLight(0x8fb8ff, 0.85);
  key.position.set(-180, 320, -140);
  group.add(key);

  const glowPoints = [
    [120, 90, 60, PALETTE.blue],
    [240, 110, 260, PALETTE.pink],
    [-80, 80, 240, PALETTE.lime],
  ];
  for (const [x, y, z, color] of glowPoints) {
    const light = new THREE.PointLight(color, 14000, 620, 2);
    light.position.set(x, y, z);
    group.add(light);
  }
}

function getSpawn(curve, t) {
  const point = curve.getPointAt(t);
  const tangent = curve.getTangentAt(t);
  return {
    position: point.clone().add(new THREE.Vector3(0, 2.2, 0)),
    heading: Math.atan2(tangent.x, tangent.z),
  };
}

import * as THREE from 'three';
import { PALETTE } from './arena.js';

const GRAVITY = -42;
const HOVER_HEIGHT = 1.35;

export function createCar(scene) {
  const group = new THREE.Group();
  scene.add(group);

  const bodyMaterial = new THREE.MeshPhysicalMaterial({
    color: PALETTE.body,
    metalness: 0.9,
    roughness: 0.18,
    clearcoat: 1.0,
    clearcoatRoughness: 0.08,
  });

  const body = new THREE.Mesh(new THREE.BoxGeometry(2.4, 0.7, 5.2), bodyMaterial);
  body.position.y = 0.45;
  group.add(body);

  const canopy = new THREE.Mesh(
    new THREE.BoxGeometry(1.5, 0.5, 2.2),
    new THREE.MeshPhysicalMaterial({
      color: 0x02050c,
      metalness: 0.6,
      roughness: 0.05,
      clearcoat: 1.0,
    })
  );
  canopy.position.set(0, 0.95, -0.3);
  group.add(canopy);

  const stripMaterial = new THREE.MeshStandardMaterial({
    color: 0x000000,
    emissive: new THREE.Color(PALETTE.blue),
    emissiveIntensity: 3.4,
  });
  for (const side of [-1, 1]) {
    const strip = new THREE.Mesh(new THREE.BoxGeometry(0.08, 0.1, 4.6), stripMaterial);
    strip.position.set(side * 1.22, 0.42, 0);
    group.add(strip);
  }

  const engineGlowMaterial = new THREE.MeshStandardMaterial({
    color: 0x000000,
    emissive: new THREE.Color(PALETTE.lime),
    emissiveIntensity: 2.5,
  });
  const engine = new THREE.Mesh(new THREE.BoxGeometry(1.6, 0.4, 0.25), engineGlowMaterial);
  engine.position.set(0, 0.45, 2.65);
  group.add(engine);

  const boostLight = new THREE.PointLight(PALETTE.lime, 60, 26, 2);
  boostLight.position.set(0, 0.6, 3.4);
  group.add(boostLight);

  return {
    group,
    engineGlowMaterial,
    boostLight,
    position: new THREE.Vector3(),
    velocity: new THREE.Vector3(),
    heading: 0,
    pitch: 0,
    roll: 0,
    boost: 100,
    grounded: false,
    raycaster: new THREE.Raycaster(),
  };
}

export function resetCar(car, spawn) {
  car.position.copy(spawn.position);
  car.velocity.set(0, 0, 0);
  car.heading = spawn.heading;
  car.pitch = 0;
  car.roll = 0;
  car.boost = 100;
  syncVisual(car);
}

export function updateCar(car, input, trackMesh, dt, raceActive) {
  const forward = new THREE.Vector3(Math.sin(car.heading), 0, Math.cos(car.heading));
  const right = new THREE.Vector3(forward.z, 0, -forward.x);

  // Ground probe.
  car.raycaster.set(car.position.clone().add(new THREE.Vector3(0, 3, 0)), new THREE.Vector3(0, -1, 0));
  car.raycaster.far = 14;
  const hits = car.raycaster.intersectObject(trackMesh, false);
  const hit = hits.length > 0 ? hits[0] : null;
  const groundHeight = hit ? hit.point.y : null;
  car.grounded = hit !== null && car.position.y - groundHeight < HOVER_HEIGHT + 1.1;

  const throttle = raceActive ? input.throttle : 0;
  const steer = input.steer;

  if (car.grounded) {
    // Hover spring keeps the car floating over the ribbon.
    const targetY = groundHeight + HOVER_HEIGHT;
    const springStrength = 68;
    const damping = 11;
    const displacement = targetY - car.position.y;
    car.velocity.y += (displacement * springStrength - car.velocity.y * damping) * dt;

    // Drive.
    const engine = 62;
    car.velocity.addScaledVector(forward, throttle * engine * dt);

    if (input.boost && car.boost > 0 && raceActive) {
      car.velocity.addScaledVector(forward, 105 * dt);
      car.boost = Math.max(0, car.boost - 30 * dt);
    } else {
      car.boost = Math.min(100, car.boost + 7 * dt);
    }

    // Steering scales with speed for arcade snap.
    const speed = car.velocity.length();
    const steerRate = 1.9 * THREE.MathUtils.clamp(speed / 32, 0.25, 1.35);
    car.heading -= steer * steerRate * dt * (input.reverse ? -1 : 1);

    // Lateral grip; drift slackens it and adds yaw energy.
    const lateral = car.velocity.dot(right);
    const grip = input.drift ? 1.6 : 9.0;
    car.velocity.addScaledVector(right, -lateral * grip * dt);
    if (input.drift) {
      car.heading -= steer * 1.15 * dt;
    }

    // Rolling resistance.
    car.velocity.multiplyScalar(1 - 0.28 * dt);

    if (input.jump && !car.jumpLatch) {
      car.velocity.y = 22;
      car.jumpLatch = true;
    }
  } else {
    car.velocity.y += GRAVITY * dt;
    // Aerial control.
    car.heading -= steer * 1.35 * dt;
    car.pitch = THREE.MathUtils.lerp(car.pitch, throttle * -0.35, dt * 3);
  }

  if (!input.jump) {
    car.jumpLatch = false;
  }

  car.position.addScaledVector(car.velocity, dt);

  // Visual lean.
  const speedRatio = THREE.MathUtils.clamp(car.velocity.length() / 70, 0, 1);
  car.roll = THREE.MathUtils.lerp(car.roll, -steer * (0.22 + speedRatio * 0.3), dt * 6);
  if (car.grounded) {
    car.pitch = THREE.MathUtils.lerp(car.pitch, 0, dt * 5);
  }

  // Boost visuals.
  const boosting = input.boost && car.boost > 0 && raceActive;
  car.engineGlowMaterial.emissiveIntensity = THREE.MathUtils.lerp(
    car.engineGlowMaterial.emissiveIntensity,
    boosting ? 9 : 2.5,
    dt * 8
  );
  car.boostLight.intensity = THREE.MathUtils.lerp(car.boostLight.intensity, boosting ? 320 : 60, dt * 8);

  syncVisual(car);
}

export function applyBoostPad(car) {
  const forward = new THREE.Vector3(Math.sin(car.heading), 0, Math.cos(car.heading));
  car.velocity.addScaledVector(forward, 26);
  car.boost = Math.min(100, car.boost + 35);
}

export function getSpeedKph(car) {
  return car.velocity.length() * 3.6;
}

function syncVisual(car) {
  car.group.position.copy(car.position);
  car.group.rotation.set(car.pitch, car.heading + Math.PI, car.roll, 'YXZ');
}

export function createRace(gates) {
  return {
    gates,
    nextGate: 0,
    countdown: 3.0,
    time: 0,
    started: false,
    finished: false,
  };
}

export function resetRace(race) {
  race.nextGate = 0;
  race.countdown = 3.0;
  race.time = 0;
  race.started = false;
  race.finished = false;
}

export function updateRace(race, carPosition, dt) {
  if (!race.started && !race.finished) {
    race.countdown -= dt;
    if (race.countdown <= 0) {
      race.countdown = 0;
      race.started = true;
    }
    return;
  }

  if (race.finished) {
    return;
  }

  race.time += dt;

  const gate = race.gates[race.nextGate];
  if (gate && carPosition.distanceTo(gate.position) < gate.radius) {
    race.nextGate += 1;
    if (race.nextGate >= race.gates.length) {
      race.finished = true;
    }
  }
}

export function isRaceActive(race) {
  return race.started && !race.finished;
}

// One-off track energy overlay — unique to the Midnight ribbon circuit.
// Lineage: Joey's iridescent dotted-wave series. A dark LED dot-matrix breathes
// beneath the racing line; a soft iridescent current flows down-track, and the
// centerline carries a faint pulse so speed always has a visual heartbeat.
export const trackEnergyVertex = /* glsl */ `
varying vec2 vUv;
void main() {
  vUv = uv;
  gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
}
`;

export const trackEnergyFragment = /* glsl */ `
precision highp float;
varying vec2 vUv;
uniform float uTime;

vec3 iridescence(float phase) {
  // Blue -> violet -> magenta sweep, never leaving the midnight family.
  return vec3(
    0.05 + 0.25 * sin(phase + 4.7),
    0.35 + 0.45 * sin(phase + 2.2),
    0.75 + 0.25 * sin(phase)
  );
}

void main() {
  // vUv.y runs along the track (0..40 wrapped), vUv.x across it.
  vec2 uv = vec2(vUv.x, fract(vUv.y));

  // LED dot matrix, denser across than along.
  vec2 cell = fract(vec2(uv.x * 30.0, vUv.y * 160.0)) - 0.5;
  float dot_ = smoothstep(0.34, 0.12, length(cell));

  // Slow current flowing down-track; each dot inherits the current's phase.
  float current = sin(vUv.y * 24.0 - uTime * 1.6) * 0.5 + 0.5;
  float shimmer = sin(vUv.y * 90.0 - uTime * 5.0 + uv.x * 6.0) * 0.5 + 0.5;

  vec3 color = iridescence(vUv.y * 12.0 - uTime * 0.8);
  float energy = dot_ * (0.045 + current * 0.12 + shimmer * 0.05);

  // Racing-line pulse down the center.
  float center = smoothstep(0.22, 0.0, abs(uv.x - 0.5));
  float pulse = pow(max(0.0, sin(vUv.y * 6.0 - uTime * 2.4)), 6.0);
  energy += center * pulse * 0.35;

  // Edge feather so the overlay dies before the rails.
  float feather = smoothstep(0.0, 0.08, uv.x) * smoothstep(1.0, 0.92, uv.x);

  gl_FragColor = vec4(color * energy * feather, energy * feather);
}
`;

