import { useRef } from 'react';
import { useFrame, useThree } from '@react-three/fiber';
import * as THREE from 'three';
import { carPhysics } from '../carState.js';

const _pos = new THREE.Vector3();
const _look = new THREE.Vector3();
const _fwd = new THREE.Vector3();
const _tmp = new THREE.Vector3();

export default function ChaseCamera() {
  const { camera } = useThree();
  const seeded = useRef(false);
  const fov = useRef(78);

  useFrame((_, dt) => {
    _fwd.set(Math.sin(carPhysics.heading), 0, Math.cos(carPhysics.heading));
    const targetPos = _tmp
      .copy(carPhysics.position)
      .addScaledVector(_fwd, -11)
      .add(new THREE.Vector3(0, 4.4, 0));
    const targetLook = carPhysics.position
      .clone()
      .addScaledVector(_fwd, 7)
      .add(new THREE.Vector3(0, 1.2, 0));

    if (!seeded.current) {
      _pos.copy(targetPos);
      _look.copy(targetLook);
      camera.position.copy(_pos);
      camera.lookAt(_look);
      seeded.current = true;
      return;
    }

    const a = 1 - Math.exp(-6 * dt);
    _pos.lerp(targetPos, a);
    _look.lerp(targetLook, a);
    camera.position.copy(_pos);
    camera.lookAt(_look);

    const want = carPhysics.isBoosting ? 88 : 78;
    fov.current = THREE.MathUtils.lerp(fov.current, want, 1 - Math.exp(-4 * dt));
    camera.fov = fov.current;
    camera.updateProjectionMatrix();
  });

  return null;
}

