import { useMemo, useRef } from 'react';
import { useFrame } from '@react-three/fiber';
import { MeshReflectorMaterial } from '@react-three/drei';
import * as THREE from 'three';
import { curve } from '../trackData.js';
import { halftoneSunVertex, halftoneSunFragment } from '../shaders/halftoneSun.js';
import { holographicFoilVertex, holographicFoilFragment } from '../shaders/holographicFoil.js';

const BLUE = 0x00a2ff;
const PINK = 0xff1f6e;
const LIME = 0x57ff6b;
const CYAN = 0x00e0ff;

function NeonRing({ t, color, scale = 1, spin = 0.12 }) {
  const ref = useRef();
  const point = curve.getPointAt(t);
  const tangent = curve.getTangentAt(t);
  const quat = useMemo(() => {
    const q = new THREE.Quaternion();
    q.setFromUnitVectors(new THREE.Vector3(0, 0, 1), tangent.clone().normalize());
    return q;
  }, [tangent.x, tangent.y, tangent.z]);

  useFrame((_, dt) => {
    if (ref.current) ref.current.rotation.z += spin * dt;
  });

  return (
    <mesh
      ref={ref}
      position={[point.x, point.y + 2, point.z]}
      quaternion={quat}
      scale={scale}
    >
      <torusGeometry args={[38, 0.35, 16, 96]} />
      <meshStandardMaterial
        color={0x000000}
        emissive={color}
        emissiveIntensity={2.2}
        toneMapped={false}
      />
    </mesh>
  );
}

function LineSphere({ position, color, radius = 28 }) {
  const geo = useMemo(() => {
    const g = new THREE.IcosahedronGeometry(radius, 2);
    const edges = new THREE.EdgesGeometry(g);
    g.dispose();
    return edges;
  }, [radius]);

