import { useMemo, useRef } from 'react';
import { useFrame } from '@react-three/fiber';
import { RigidBody, useRapier } from '@react-three/rapier';
import * as THREE from 'three';
import { getSpawn, BOOST_PAD_T_VALUES, curve } from '../trackData.js';
import { useRaceStore } from '../state.js';
import { carPhysics } from '../carState.js';
import { useInput } from '../useInput.js';
import { holographicFoilVertex, holographicFoilFragment } from '../shaders/holographicFoil.js';

const HOVER_HEIGHT = 1.35;
const BOOST_PAD_RADIUS = 12;

export default function Car() {
  const body = useRef();
  const engineMat = useRef();
  const boostLight = useRef();
  const foilMat = useRef();
  const getInput = useInput();
  const { world } = useRapier();
  const jumpLatch = useRef(false);
  const resetLatch = useRef(false);
  const padCooldown = useRef([0, 0, 0, 0]);
  const spawn = useMemo(() => getSpawn(), []);

  const bodyMat = useMemo(
    () =>
      new THREE.MeshPhysicalMaterial({
        color: 0x0a0c12,
        metalness: 0.92,
        roughness: 0.14,
        clearcoat: 1,
        clearcoatRoughness: 0.06,
        iridescence: 1,
        iridescenceIOR: 1.4,
        iridescenceThicknessRange: [120, 420],
      }),
    []
  );

  const foil = useMemo(
    () =>
      new THREE.ShaderMaterial({
        vertexShader: holographicFoilVertex,
        fragmentShader: holographicFoilFragment,
        uniforms: {
          uTime: { value: 0 },
          uHeat: { value: 0.2 },
          uFlow: { value: 0 },
        },
        transparent: true,
        depthWrite: false,
        blending: THREE.AdditiveBlending,
      }),
    []
  );

  useFrame((_, dt) => {
    const rb = body.current;
    if (!rb) return;

    const input = getInput();
    const phase = useRaceStore.getState().phase;
    const racing = phase === 'racing';

    useRaceStore.getState().tickCountdown(dt);
    useRaceStore.getState().tickRaceTime(dt);

    const pos = rb.translation();
    const linvel = rb.linvel();
    const rot = rb.rotation();
    const q = new THREE.Quaternion(rot.x, rot.y, rot.z, rot.w);
    const euler = new THREE.Euler().setFromQuaternion(q, 'YXZ');
    let heading = euler.y;

    // 4-corner hover raycasts
    const corners = [
      [0.9, 0, 1.6],
      [-0.9, 0, 1.6],
      [0.9, 0, -1.6],
      [-0.9, 0, -1.6],
    ];
    let grounded = false;
    let avgGroundY = 0;
    let hits = 0;
    const origin = { x: 0, y: 0, z: 0 };
    const dir = { x: 0, y: -1, z: 0 };

    for (const [ox, oy, oz] of corners) {
      origin.x = pos.x + ox;
      origin.y = pos.y + 3 + oy;
      origin.z = pos.z + oz;
      const hit = world.castRay(
        { origin, dir, toi: 14 },
        14,
        true
      );
      if (hit) {
        const gy = origin.y - hit.timeOfImpact;
        if (pos.y - gy < HOVER_HEIGHT + 1.2) {
          grounded = true;
          avgGroundY += gy;
          hits += 1;
        }
      }
    }

    const forward = new THREE.Vector3(Math.sin(heading), 0, Math.cos(heading));
    const right = new THREE.Vector3(forward.z, 0, -forward.x);
    const vel = new THREE.Vector3(linvel.x, linvel.y, linvel.z);

    if (grounded && hits > 0) {
      avgGroundY /= hits;
      const targetY = avgGroundY + HOVER_HEIGHT;
      const disp = targetY - pos.y;
      const spring = disp * 68 - vel.y * 11;
      rb.applyImpulse({ x: 0, y: spring * dt * 120, z: 0 }, true);

      const throttle = racing ? input.throttle : 0;
      rb.applyImpulse(
        {
          x: forward.x * throttle * 62 * dt * 120,
          y: 0,
          z: forward.z * throttle * 62 * dt * 120,
        },
        true
      );

      let boosting = false;
      if (input.boost && carPhysics.boost > 0 && racing) {
        rb.applyImpulse(
          {
            x: forward.x * 105 * dt * 120,
            y: 0,
            z: forward.z * 105 * dt * 120,
          },
          true
        );
        carPhysics.boost = Math.max(0, carPhysics.boost - 30 * dt);
        boosting = true;
      } else {
        carPhysics.boost = Math.min(100, carPhysics.boost + 7 * dt);
      }
      carPhysics.isBoosting = boosting;

      const speed = Math.hypot(linvel.x, linvel.z);
      const steerRate = 1.9 * THREE.MathUtils.clamp(speed / 32, 0.25, 1.35);
      heading -= input.steer * steerRate * dt * (input.reverse ? -1 : 1);

      const lateral = vel.dot(right);
      const grip = input.drift ? 1.6 : 9.0;
      rb.applyImpulse(
        {
          x: -right.x * lateral * grip * dt * 120,
          y: 0,
          z: -right.z * lateral * grip * dt * 120,
        },
        true
      );
      if (input.drift) heading -= input.steer * 1.15 * dt;

      // Rolling drag
      rb.applyImpulse(
        {
          x: -linvel.x * 0.28 * dt * 120,
          y: 0,
          z: -linvel.z * 0.28 * dt * 120,
        },
        true
      );

      if (input.jump && !jumpLatch.current) {
        rb.applyImpulse({ x: 0, y: 22 * 120, z: 0 }, true);
        jumpLatch.current = true;
      }
    } else {
      heading -= input.steer * 1.35 * dt;
      carPhysics.isBoosting = false;
    }

    if (!input.jump) jumpLatch.current = false;

    // Apply yaw
    const nextQ = new THREE.Quaternion().setFromEuler(new THREE.Euler(0, heading, 0, 'YXZ'));
    rb.setRotation({ x: nextQ.x, y: nextQ.y, z: nextQ.z, w: nextQ.w }, true);

    // Boost pads
    for (let i = 0; i < BOOST_PAD_T_VALUES.length; i++) {
      padCooldown.current[i] = Math.max(0, padCooldown.current[i] - dt);
      const p = curve.getPointAt(BOOST_PAD_T_VALUES[i]);
      const d = Math.hypot(pos.x - p.x, pos.z - p.z);
      if (padCooldown.current[i] <= 0 && d < BOOST_PAD_RADIUS) {
        rb.applyImpulse(
          {
            x: forward.x * 26 * 120,
            y: 0,
            z: forward.z * 26 * 120,
          },
          true
        );
        carPhysics.boost = Math.min(100, carPhysics.boost + 35);
        padCooldown.current[i] = 1.5;
      }
    }

    // Publish for camera / HUD
    carPhysics.position.set(pos.x, pos.y, pos.z);
    carPhysics.heading = heading;
    carPhysics.velocity.set(linvel.x, linvel.y, linvel.z);
    useRaceStore.getState().checkGate(carPhysics.position);

    // Visuals
    if (engineMat.current) {
      const target = carPhysics.isBoosting ? 5 : 1.5;
      engineMat.current.emissiveIntensity = THREE.MathUtils.lerp(
        engineMat.current.emissiveIntensity,
        target,
        dt * 8
      );
    }
    if (boostLight.current) {
      boostLight.current.intensity = THREE.MathUtils.lerp(
        boostLight.current.intensity,
        carPhysics.isBoosting ? 140 : 25,
        dt * 8
      );
    }
    if (foilMat.current) {
      foilMat.current.uniforms.uTime.value += dt;
      foilMat.current.uniforms.uHeat.value = carPhysics.isBoosting ? 1 : 0.25;
      foilMat.current.uniforms.uFlow.value = Math.min(1, Math.hypot(linvel.x, linvel.z) / 60);
    }

    // Reset
    if (input.reset && !resetLatch.current) {
      resetLatch.current = true;
      rb.setTranslation(
        { x: spawn.position.x, y: spawn.position.y, z: spawn.position.z },
        true
      );
      rb.setLinvel({ x: 0, y: 0, z: 0 }, true);
      rb.setAngvel({ x: 0, y: 0, z: 0 }, true);
      const rq = new THREE.Quaternion().setFromEuler(
        new THREE.Euler(0, spawn.heading, 0, 'YXZ')
      );
      rb.setRotation({ x: rq.x, y: rq.y, z: rq.z, w: rq.w }, true);
      carPhysics.boost = 100;
      if (phase === 'finished') useRaceStore.getState().reset();
    }
    if (!input.reset) resetLatch.current = false;
  });

  return (
    <RigidBody
      ref={body}
      colliders="cuboid"
      mass={120}
      linearDamping={0.9}
      angularDamping={4}
      position={[spawn.position.x, spawn.position.y, spawn.position.z]}
      rotation={[0, spawn.heading, 0]}
      enabledRotations={[false, true, false]}
      ccd
    >
      <group>
        <mesh material={bodyMat} position={[0, 0.45, 0]}>
          <boxGeometry args={[2.4, 0.7, 5.2]} />
        </mesh>
        <mesh
          position={[0, 0.45, 0]}
          material={foil}
          ref={(m) => {
            if (m) foilMat.current = m.material;
          }}
          scale={[1.02, 1.02, 1.02]}
        >
          <boxGeometry args={[2.4, 0.7, 5.2]} />
        </mesh>
        <mesh position={[0, 0.95, -0.3]}>
          <boxGeometry args={[1.5, 0.5, 2.2]} />
          <meshPhysicalMaterial
            color={0x02050c}
            metalness={0.6}
            roughness={0.05}
            clearcoat={1}
            transmission={0.35}
            thickness={0.4}
          />
        </mesh>
        {[-1, 1].map((side) => (
          <mesh key={side} position={[side * 1.22, 0.42, 0]}>
            <boxGeometry args={[0.08, 0.1, 4.6]} />
            <meshStandardMaterial
              color={0x000000}
              emissive={0x00a2ff}
              emissiveIntensity={3.4}
              toneMapped={false}
            />
          </mesh>
        ))}
        <mesh position={[0, 0.45, 2.65]}>
          <boxGeometry args={[1.6, 0.4, 0.25]} />
          <meshStandardMaterial
            ref={engineMat}
            color={0x000000}
            emissive={0x57ff6b}
            emissiveIntensity={1.5}
            toneMapped={false}
          />
        </mesh>
        <pointLight
          ref={boostLight}
          color={0x57ff6b}
          intensity={25}
          distance={26}
          decay={2}
          position={[0, 0.6, 3.4]}
        />
      </group>
    </RigidBody>
  );
}

import { useMemo, useRef } from 'react';
import { useFrame, useThree } from '@react-three/fiber';
import { Text } from '@react-three/drei';
import * as THREE from 'three';
import { useRaceStore } from '../state.js';
import { carPhysics } from '../carState.js';

function GlassPanel({ width, height, position, rotation = [0, 0, 0] }) {
  return (
    <mesh position={position} rotation={rotation}>
      <planeGeometry args={[width, height]} />
      <meshPhysicalMaterial
        color={0xddeeff}
        transmission={0.9}
        thickness={0.35}
        roughness={0.55}
        ior={1.2}
        transparent
        opacity={0.98}
        side={THREE.DoubleSide}
      />
    </mesh>
  );
}

export default function Hud3D() {
  const { camera } = useThree();
  const root = useRef();
  const boostFill = useRef();
  const speedText = useRef();
  const raceText = useRef();
  const centerText = useRef();
  const centerSub = useRef();
  const centerGroup = useRef();
  const bob = useRef(0);

  // Attach HUD under camera once
  useMemo(() => {
    // no-op; attachment done in useFrame first pass via scene graph
  }, []);

  useFrame((_, dt) => {
    if (!root.current) return;
    if (root.current.parent !== camera) {
      camera.add(root.current);
    }

    bob.current += dt;
    root.current.position.set(0, Math.sin(bob.current * Math.PI) * 0.01, -3.2);

    const speed = Math.round(carPhysics.velocity.length() * 3.6);
    if (speedText.current) {
      speedText.current.text = String(speed).padStart(3, '0');
    }

    if (boostFill.current) {
      boostFill.current.scale.x = Math.max(0.001, carPhysics.boost / 100);
    }

    const { phase, countdown, raceTime, nextGate, gateCount } = useRaceStore.getState();
    const mins = Math.floor(raceTime / 60);
    const secs = (raceTime % 60).toFixed(2).padStart(5, '0');
    const timer = `${String(mins).padStart(2, '0')}:${secs}`;
    const gateLabel =
      phase === 'finished'
        ? 'FINISH'
        : `GATE ${Math.min(nextGate + 1, gateCount)}/${gateCount}`;
    if (raceText.current) raceText.current.text = `${gateLabel}\n${timer}`;

    let showCenter = false;
    let big = '';
    let sub = '';
    if (phase === 'countdown') {
      showCenter = true;
      const c = Math.ceil(countdown);
      big = c > 0 ? String(c) : 'GO';
      sub = 'GET READY';
    } else if (phase === 'racing' && raceTime < 1.2) {
      showCenter = true;
      big = 'GO';
      sub = 'FULL SEND';
    } else if (phase === 'finished') {
      showCenter = true;
      big = 'FINISH';
      sub = 'PRESS R TO RESTART';
    }
    if (centerGroup.current) centerGroup.current.visible = showCenter;
    if (centerText.current && showCenter) centerText.current.text = big;
    if (centerSub.current && showCenter) centerSub.current.text = sub;
  });

  return (
    <group ref={root}>
      {/* Left — speed */}
      <group position={[-0.8, -0.5, 0]} rotation={[0, THREE.MathUtils.degToRad(12), 0]}>
        <GlassPanel width={0.9} height={0.46} position={[0, 0.03, 0]} />
        <Text
          ref={speedText}
          position={[0, 0.1, 0.01]}
          fontSize={0.16}
          color="#00a2ff"
          anchorX="center"
          anchorY="middle"
          outlineWidth={0.008}
          outlineColor="#003a66"
        >
          000
        </Text>
        <Text
          position={[0, -0.02, 0.01]}
          fontSize={0.05}
          color="#00a2ff"
          anchorX="center"
          anchorY="middle"
        >
          KM/H
        </Text>
        <mesh position={[0, -0.16, 0.005]}>
          <boxGeometry args={[0.72, 0.024, 0.008]} />
          <meshStandardMaterial color={0x0d1f14} transparent opacity={0.8} />
        </mesh>
        <mesh
          ref={boostFill}
          position={[-0.36, -0.16, 0.008]}
          geometry={useMemo(() => {
            const g = new THREE.BoxGeometry(0.72, 0.024, 0.01);
            g.translate(0.36, 0, 0);
            return g;
          }, [])}
        >
          <meshStandardMaterial
            color={0x000000}
            emissive={0x57ff6b}
            emissiveIntensity={2.8}
            toneMapped={false}
          />
        </mesh>
      </group>

      {/* Right — gate / timer */}
      <group position={[0.8, -0.5, 0]} rotation={[0, THREE.MathUtils.degToRad(-12), 0]}>
        <GlassPanel width={0.9} height={0.46} position={[0, 0.03, 0]} />
        <Text
          ref={raceText}
          position={[0, 0.04, 0.01]}
          fontSize={0.08}
          color="#ff1f6e"
          anchorX="center"
          anchorY="middle"
          textAlign="center"
          outlineWidth={0.004}
          outlineColor="#4a0020"
        >
          {`GATE 1/4\n00:00.00`}
        </Text>
      </group>

      {/* Center countdown */}
      <group ref={centerGroup} position={[0, 0.24, 0]}>
        <GlassPanel width={1.22} height={0.58} position={[0, 0, 0]} />
        <Text
          ref={centerText}
          position={[0, 0.06, 0.01]}
          fontSize={0.28}
          color="#ff1f6e"
          anchorX="center"
          anchorY="middle"
          outlineWidth={0.012}
          outlineColor="#4a0020"
        >
          3
        </Text>
        <Text
          ref={centerSub}
          position={[0, -0.16, 0.01]}
          fontSize={0.06}
          color="#9fb4d8"
          anchorX="center"
          anchorY="middle"
        >
          GET READY
        </Text>
      </group>
    </group>
  );
}

